    ('5d28b0a1-7a7e-4b06-a3e0-711a5f66b3c8'::uuid, 'Siyah Ceket Pantolon Takım', 'Şal yaka ve kolsuz tasarımıyla modern bir görünüm sunan bu ceket, şık ve rahat bir kullanım için idealdir. Ön kısmında bulunan iki adet büyük düğme detayı, cekete özgün bir hava katmaktadır. Şık ve modern bir görünüm sunan bu siyah pantolon, yüksek bel kesimi ve bol paça tasarımıyla dikkat çekiyor. Günlük kullanımda veya özel davetlerde rahatlıkla tercih edilebilir.', null, 'available', 'fashion', 9, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb, '{"L":1,"M":2,"S":2,"XL":1,"XS":1,"2XL":1,"3XL":1}'::jsonb, '{"setItems":[{"chips":{"fit":"Rahat","hem":null,"rise":null,"length":"Crop","sleeves":"Kolsuz","neckline":"V yaka","decollete":null},"family":"ust-giyim","category":"bluz"},{"chips":{"fit":"Rahat","hem":"Bol","rise":"Yüksek bel","length":"Normal","sleeves":null,"neckline":null,"decollete":null},"family":"alt-giyim","category":"pantolon"}],"aiModelId":"studio:selin","uploadKind":"takim","colorGroupId":"4c4c3ecd-f1c4-4e3b-8fca-6151c1b165c9","colorSiblingIds":["5d28b0a1-7a7e-4b06-a3e0-711a5f66b3c8","b1d3b265-66d4-4e25-ac00-4a50c4938dd0","9b058a7a-11a7-47ae-9d13-88b5458a1c75"],"lifestyleModelIds":["studio:selin","studio:selin"]}'::jsonb, '["https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/8c86ab0d-cdda-4f29-af7d-769b49ae1cc3.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/4150e18b-31aa-440f-bc25-8292e3692c03.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/ed7081c2-9cce-4e27-85e0-6b319bd62dfa.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/ori