    ('398df743-a4b3-4557-b729-da7253961b64'::uuid, 'Beyaz Kemerli Pantolon', 'Yüksek belli, regular kesim kahverengi pantolon. Düz paça detayı ile şık bir görünüm sunar.', null, 'available', 'fashion', 15, '["24","26","28","30","32","34","36","38","40","42","44","46","48","50","52"]'::jsonb, '{"24":1,"26":1,"28":1,"30":1,"32":1,"34":1,"36":1,"38":1,"40":1,"42":1,"44":1,"46":1,"48":1,"50":1,"52":1}'::jsonb, '{"fit":"Regular","rise":"Yüksek bel","color":"Beyaz","length":"Normal","neckHem":"Düz","ornament":"Kemerli","aiModelId":"studio:selin","colorGroupId":"5764f995-7986-4c04-b346-aa0f7a35edee","colorSiblingIds":["b69a3fd1-4a48-4a52-8ef1-8b39f92456c1","398df743-a4b3-4557-b729-da7253961b64"],"lifestyleModelIds":["studio:selin","studio:selin"]}'::jsonb, '["https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/1d8364f4-56cc-4ab6-92b0-468d40ac3f4d.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/3609f029-5814-4a22-82a0-0ad8a8ca28cd.webp","","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/marketplace/8fa711bf-1792-4b9b-b29d-9bbaaca08345.png"]'::jsonb, '["","","","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/marketplace/8fa711bf-1792-4b9b-b29d-9bbaaca08345.png"]'::jsonb, '["https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/lifestyle/a7ce6de4-0365-4bcc-b37f-30428a31cb60.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/lifestyle/4f4e19eb-6ed0-4c34-ab