    ('fc78f5ef-53b9-4f85-8de6-80b3c63fd3e3'::uuid, 'Navy Midi Jean Elbise', 'Navy lacivert, vücuda oturan midi elbise. Kumaş denim benzeri, hafif esnek; mat durur, parlamaz. Açık renk kot dikişi (topstitch) yakada, kol evinde ve etek ucunda görünür. Sivri polo yaka, V yaka. Kolsuz; kol evi omuzu biraz örter, sütyen askısı kolay gizlenir. Önde üç gümüş düğme — süs, fermuar değil. Belde yatay büzgü; göbek şişirmez, beli toplar. Fermuar yanda, kol evinin hemen altında, kumaş rengine yakın ve ince. Sırtta fermuar yok; orta dikiş. Etek ucunda yırtmaç var. Boyu diz altı midi, kalem etek silüeti.', null, 'available', 'fashion', 3, '["XS","S","M","L","XL","2XL","3XL"]'::jsonb, '{"L":1,"M":1,"S":1,"XL":0,"XS":0,"2XL":0,"3XL":0}'::jsonb, '{"color":"Navy","gender":"Kadın","length":"Midi","zipper":"Yan fermuar","sleeves":"Kolsuz","stretch":"Hafif esnek","neckline":"V yaka","aiModelId":"studio:selin","decollete":"Hafif","silhouette":"Vücuda oturan","colorGroupId":"ae723d38-5e4b-45c4-b83d-437ece980af1","manualListing":true,"colorSiblingIds":["fc78f5ef-53b9-4f85-8de6-80b3c63fd3e3","0867af66-9b0a-421b-981d-d01ddfb5d4e6"]}'::jsonb, '["https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/84e4ab57-674f-4bbc-abc5-8a36038177ea.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/61f9ae07-34dd-4a43-9cde-6a1c6d2861a3.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/1a946418-93cd-48a4-a2a0-c811964ad77d.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/5ab99f80-7cf3-49c1-8152-074eadcedd6f.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/e6f3f86b-d632-4da7-ad67-db391988b130.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/e40faec2-5f51-42f5-9059-90d7e2698875.webp"]'::jsonb, '["","","","","",""]'::jsonb, '[]'::jsonb)
  ) as s(id, title, description, description_html, status, product_type, stock, sizes, size_stocks, features, images, marketplace_images, lifestyle_images)
  left join public.tr_products p on p.id = s.id
  where p.id is null
     or p.title is distinct from s.title
     or p.description is distinct from s.description
     or p.description_html is distinct from s.description_html
     or p.status::text is distinct from s.status
     or p.product_type is distinct from s.product_type
     or p.stock is distinct from s.stock
     or p.sizes is distinct from s.sizes
     or p.size_stocks is distinct from s.size_stocks
     or p.features is distinct from s.features
     or p.images is distinct from s.images
     or p.marketplace_images is distinct from s.marketplace_images
     or p.lifestyle_images is distinct from s.lifestyle_images
     or p.merged_into is not null;
  if changed > 0 then
    raise exception 'F6: % product(s) changed since the snapshot; re-run the script', changed;
  end if;
end
