-- Midi Jean Elbise (merged: 2 colours)
update public.tr_products set
  product_type = 'advanced',
  stock = 6,
  sizes = '["XS","S","M","L","XL","2XL","3XL"]'::jsonb,
  size_stocks = '{}'::jsonb,
  title = 'Midi Jean Elbise',
  description = 'Espresso kahverengi, vücuda oturan midi elbise. Kumaş denim benzeri, hafif esnek; mat durur, parlamaz. Açık renk kot dikişi (topstitch) yakada, kol evinde ve etek ucunda görünür.

Sivri polo yaka, V yaka. Kolsuz; kol evi omuzu biraz örter, sütyen askısı kolay gizlenir. Önde üç gümüş düğme — süs, fermuar değil. Belde yatay büzgü; göbek şişirmez, beli toplar.

Fermuar yanda, kol evinin hemen altında, kumaş rengine yakın ve ince. Sırtta fermuar yok; orta dikiş. 
Etek ucunda yırtmaç var. Boyu diz altı midi, kalem etek silüeti.',
  description_html = null,
  images = '["https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/22421a35-6947-4251-9992-262ba143c843.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/89bfcd1a-995a-454c-9820-358d5145f680.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/76f17426-0c7d-4667-aa96-0f8ab4c0a2d9.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/9e0247b9-5de4-40b5-ab9d-8268f044fc20.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/e49393ed-792c-4e5e-a812-7203ff4b3491.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/f65f5e77-4938-492b-8d65-3e73c15c95a4.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/c4509c22-95e4-4198-a471-ee87d6f4e639.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/84e4ab57-674f-4bbc-abc5-8a36038177ea.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/61f9ae07-34dd-4a43-9cde-6a1c6d2861a3.webp","https://qjxclaggqzhfaqihwdle.supabase.co/storage/v1/object/public/tr-assets/6202207c-9b0f-4c0e-be3b-0ea8df24cf52/2b2b1a07-3a58-4422-bc67-e274b0fa6d1d/original/